	[TestMethod]
	public void align_flex_end_with_row_reverse()
	{
		var root = CreateNode();
		root.Style.AlignItems = Align.FlexEnd;
		root.Style.PositionType = PositionType.Absolute;
		root.Style.FlexWrap = Wrap.Wrap;
		root.Style.Width = StyleLength.Points( 100 );
		root.Style.Height = StyleLength.Points( 75 );

		var root_child0 = CreateNode();
		root_child0.Style.SetMargin( Edge.Left, StyleLength.Points( 3 ) );
		root_child0.Style.SetMargin( Edge.Right, StyleLength.Points( 5 ) );
		root_child0.Style.Width = StyleLength.Points( 50 );
		root_child0.Style.Height = StyleLength.Points( 50 );
		root.InsertChild( root_child0, 0 );

		var root_child1 = CreateNode();
		root_child1.Style.Width = StyleLength.Points( 50 );
		root_child1.Style.Height = StyleLength.Points( 50 );
		root.InsertChild( root_child1, 1 );
		root.CalculateLayout( float.NaN, float.NaN, Direction.LTR );

		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Left, "root.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Top, "root.Top" );
		AssertEq( 100, FixtureGeometry.GetRect( root, true ).Width, "root.Width" );
		AssertEq( 75, FixtureGeometry.GetRect( root, true ).Height, "root.Height" );

		AssertEq( 3, FixtureGeometry.GetRect( root_child0, true ).Left, "root_child0.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root_child0, true ).Top, "root_child0.Top" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child0, true ).Width, "root_child0.Width" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child0, true ).Height, "root_child0.Height" );

		AssertEq( 58, FixtureGeometry.GetRect( root_child1, true ).Left, "root_child1.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root_child1, true ).Top, "root_child1.Top" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child1, true ).Width, "root_child1.Width" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child1, true ).Height, "root_child1.Height" );

		root.CalculateLayout( float.NaN, float.NaN, Direction.RTL );

		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Left, "root.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Top, "root.Top" );
		AssertEq( 100, FixtureGeometry.GetRect( root, true ).Width, "root.Width" );
		AssertEq( 75, FixtureGeometry.GetRect( root, true ).Height, "root.Height" );

		AssertEq( 45, FixtureGeometry.GetRect( root_child0, true ).Left, "root_child0.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root_child0, true ).Top, "root_child0.Top" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child0, true ).Width, "root_child0.Width" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child0, true ).Height, "root_child0.Height" );

		AssertEq( -8, FixtureGeometry.GetRect( root_child1, true ).Left, "root_child1.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root_child1, true ).Top, "root_child1.Top" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child1, true ).Width, "root_child1.Width" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child1, true ).Height, "root_child1.Height" );
	}

